    int randvalue = RandomNumberGenerator.GetInt32(bytes.Length);
    int randbit = RandomNumberGenerator.GetInt32(bitW.Length);

    try { bytes[randvalue] += bitW[randbit]; }
    catch { bytes[randvalue] -= bitW[randbit]; }

